<script setup lang="ts">
import { computed, ref } from 'vue';
import coverage from 'virtual:coverage';
import review from '../../editorial/existing-content-review.json';
import { collections, contentManifest, getCollection, media, worlds } from '../content';

const search = ref('');
const world = ref('');
const status = ref('');
const reviewById = new Map(review.items.map(item => [item.id, item]));
const rows = contentManifest.documents.map(document => ({
  document,
  review: reviewById.get(document.id),
  dossiers: collections.filter(item => item.kind === 'dossier' && item.itemIds.includes(document.id)),
}));
const visible = computed(() => rows.filter(row =>
  (!search.value || `${row.document.title} ${row.document.id}`.toLowerCase().includes(search.value.toLowerCase()))
  && (!world.value || row.document.worlds.includes(world.value as typeof row.document.primaryWorld))
  && (!status.value || (status.value === 'unverified' ? row.document.verification.status === 'unverified' : row.review?.disposition === status.value)),
));
const mediaToReview = media.filter(item => item.rights.status === 'unverified');
</script>
<template>
  <main id="main-content" class="editorial-page" tabindex="-1">
    <header class="editorial-heading"><p class="eyebrow">EDITORIAL / LOCAL WORKSPACE</p><h1>The content desk<span>.</span></h1><p>Review recorded {{ coverage.auditReviewedAt }}. Source verification and editorial review are separate records.</p></header>
    <dl class="editorial-totals"><div><dt>Documents</dt><dd>{{ coverage.totals.documents }}</dd></div><div><dt>Collections</dt><dd>{{ coverage.totals.dossiers }}</dd></div><div><dt>Verified documents</dt><dd>{{ coverage.evidence.verifiedDocuments.length }}</dd></div><div><dt>Need source checks</dt><dd>{{ coverage.evidence.unverifiedDocuments.length }}</dd></div></dl>
    <section class="coverage-section" aria-labelledby="world-coverage"><h2 id="world-coverage">World coverage</h2><div class="world-coverage"><article v-for="item in coverage.worldCoverage" :key="item.id"><h3>{{ item.title }}</h3><p>{{ item.kinds.feature }} features · {{ item.kinds.note }} notes · {{ item.kinds.phrase }} local words</p><ul><li v-for="id in item.dossierIds" :key="id"><RouterLink :to="`/topics/${getCollection(id).slug}`">{{ getCollection(id).title }} ↗</RouterLink></li></ul></article></div></section>
    <section class="coverage-section" aria-labelledby="document-review"><div class="review-heading"><h2 id="document-review">Document review</h2><p aria-live="polite">{{ visible.length }} records</p></div><form class="review-filters" @submit.prevent><label>Find a document<input v-model="search" type="search" /></label><label>World<select v-model="world"><option value="">All worlds</option><option v-for="item in worlds" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>Review queue<select v-model="status"><option value="">All records</option><option value="unverified">Need source checks</option><option value="deepen">Deepen</option><option value="merge">Consider merging</option><option value="retain">Retain</option></select></label></form>
      <div class="review-table"><table><caption class="sr-only">Canonical content, evidence and editorial review</caption><thead><tr><th scope="col">Document</th><th scope="col">Evidence</th><th scope="col">Collections</th><th scope="col">Review</th></tr></thead><tbody><tr v-for="row in visible" :key="row.document.id"><td><RouterLink :to="row.document.canonicalPath">{{ row.document.title }} ↗</RouterLink><small>{{ row.document.id }}</small><span>{{ row.document.primaryWorld }} / {{ row.document.kind }}</span></td><td><strong :class="{'needs-check':row.document.verification.status === 'unverified'}">{{ row.document.verification.status }}</strong><small v-if="row.document.verification.status === 'verified'">{{ row.document.verification.verifiedAt }}</small><span>{{ row.document.sourceRefs.length }} sources</span></td><td><ul v-if="row.dossiers.length"><li v-for="item in row.dossiers" :key="item.id"><RouterLink :to="`/topics/${item.slug}`">{{ item.title }}</RouterLink></li></ul><span v-else>World and topic indexes</span></td><td><details v-if="row.review"><summary>{{ row.review.disposition }}</summary><p>{{ row.review.reason }}</p><p v-if="row.review.mergedInto">Suggested destination: {{ row.review.mergedInto }}</p></details><span v-else>New edition</span></td></tr></tbody></table></div>
    </section>
    <section class="coverage-section" aria-labelledby="media-records"><h2 id="media-records">Media records</h2><p>{{ mediaToReview.length }} illustrations have incomplete provenance or rights records.</p><ul class="media-review"><li v-for="item in mediaToReview" :key="item.id"><a :href="item.src">{{ item.id }} ↗</a><span>{{ item.use }} / {{ item.rights.status }}</span></li></ul></section>
  </main>
</template>
<style scoped>
