t-size:12px;font-weight:500;color:#286343}.needs-check{color:var(--accent)}td ul{padding-left:16px;margin:0;font-size:13px;min-width:140px}td li+li{margin-top:9px}summary{cursor:pointer;padding:0 0 8px;text-transform:capitalize}details{min-width:130px}details[open]{min-width:220px}details p{margin:10px 0;color:var(--ink-soft);font-size:13px}.media-review{list-style:none;margin:20px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0 35px}.media-review li{padding:16px 0;border-bottom:1px solid var(--rule);font-size:14px}.media-review span{display:block;color:var(--ink-muted);font-size:12px;margin-top:7px}@media(max-width:850px){.world-coverage{grid-template-columns:1fr 1fr}.editorial-totals{grid-template-columns:1fr 1fr}}@media(max-width:550px){.review-filters{display:grid;grid-template-columns:1fr 1fr}.review-filters label:first-child{grid-column:1/-1}.review-filters input{width:100%}.world-coverage,.media-review{grid-template-columns:1fr}.editorial-page{padding-top:30px}.editorial-totals dd{font-size:36px}}
</style>
